insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('payment.overview','موتور پرداخت','RAVA پرداخت را از سفارش جدا نگه می‌دارد تا بتوان برای هر سایت درگاه مناسب را بدون تغییر هسته فروشگاه متصل کرد.','فعال بودن فروشگاه به معنی فعال بودن هر درگاه پرداخت نیست؛ درگاه و تنظیمات آن باید جداگانه پیکربندی شوند.','Payment Engine','RAVA separates payments from orders so each tenant can use an appropriate gateway without rebuilding Commerce.','Commerce availability does not automatically enable a gateway; each gateway must be configured separately.',true),
('payment.verify','تأیید پرداخت','برگشت مشتری از درگاه فقط یک پیام اولیه است. سیستم باید پرداخت را مستقیماً از سرور درگاه Verify کند و فقط بعد سفارش را Paid کند.','هیچ پارامتر URL یا Callback به‌تنهایی مدرک پرداخت نیست.','Payment verification','A browser callback is only an initial signal. RAVA must verify the payment server-to-server with the provider before marking an order Paid.','Never trust callback or URL parameters alone as proof of payment.',true),
('payment.idempotency','جلوگیری از پرداخت تکراری','برای هر تلاش پرداخت کلید یکتا ثبت می‌شود تا Refresh، دوبار کلیک یا Callback تکراری باعث ثبت دوباره پرداخت نشود.',null,'Payment idempotency','Each payment attempt uses a unique idempotency key so refreshes, double clicks and repeated callbacks cannot duplicate a payment.',null,true),
('payment.secrets','اطلاعات محرمانه درگاه','کلیدها و رمزهای درگاه فقط در محیط امن سرور نگهداری می‌شوند و هرگز به مرورگر مشتری ارسال نمی‌شوند.','Secret درگاه را داخل فیلد عمومی، کد سمت کاربر یا لاگ خام قرار نده.','Gateway secrets','Gateway credentials live only in protected server-side secret storage and are never exposed to customer browsers.','Never place gateway secrets in public fields, client code or raw logs.',true)
